<script setup lang="ts">
// Personal cloud library, direct provider imports and cross-match weapon records.
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { CLOUD_API, cloudSession, setCloudSession, signedIn, steamLoginUrl, keepCloudVoice, cloudBusy, cloudProgress } from '@/cloud/client'
import { extensionRequest, type ConnectorState, type SourceMatch } from '@/cloud/extension'
import { useRecentDemos } from '@/viewer/ingest/useRecentDemos'
import { fmtSize, mapImage, prettyMap } from '@/viewer/domain/demoMeta'
import { demoPath, UPLOAD_PATH } from '@/app/paths'
import { useI18n } from '@/app/i18n'
const { t } = useI18n()
const route = useRoute(); const router = useRouter(); const recent = useRecentDemos()
const error = ref(''); const notice = ref(''); const loading = ref(false); const installed = ref(false)
const nickname = ref('Al1askhan'); const search = ref(''); const sort = ref('date')
const state = ref<ConnectorState>({ matches: [], active: [] })
const extensionDownload = import.meta.env.BASE_URL + 'cs2d-companion.zip'
const owner = '76561198920126438'
const selected = ref<string[]>([])
const records = computed(() => recent.list.value.filter(m => `${m.title || m.fileName} ${m.map}`.toLowerCase().includes(search.value.toLowerCase())).map(m => {
  const p = m.analysis?.players.find(p => p.steamId === owner)
  const deagle = p?.weapons.find(w => w.weapon === 'deagle')
  return { ...m, me: p, deagle }
}).sort((a,b) => sort.value === 'deagle' ? (b.deagle?.kills ?? -1)-(a.deagle?.kills ?? -1) || (b.deagle?.hsPercent ?? 0)-(a.deagle?.hsPercent ?? 0) : sort.value === 'deagleHs' ? (b.deagle?.headshots ?? -1)-(a.deagle?.headshots ?? -1) : sort.value === 'hs' ? (b.me?.hsPercent ?? -1)-(a.me?.hsPercent ?? -1) : b.savedAt-a.savedAt))
const imports = computed(() => state.value.matches.filter(m => !recent.list.value.some(r => r.source === m.source && r.sourceId === m.id)))
async function run(task: () => Promise<void>) { loading.value = true; error.value = ''; notice.value = ''; try { await task() } catch(e) { error.value = e instanceof Error ? e.message : String(e) } finally { loading.value = false } }
async function pair() {
  await extensionRequest('CLOUD_CONFIG', { api: CLOUD_API, token: cloudSession(), keepVoice: keepCloudVoice.value })
}
async function updateState() {
  if (!installed.value) return
  state.value = await extensionRequest<ConnectorState>('SOURCES_STATE', {}, 5000)
}
async function syncFaceit() { await run(async () => { await pair(); await extensionRequest('FACEIT_SYNC', { nickname: nickname.value }, 90000); await updateState() }) }
async function syncSteam() { await run(async () => { await pair(); await extensionRequest('STEAM_SYNC'); notice.value = t('cloud.steamOpened') }) }
async function importSelected() { await run(async () => { await pair(); for (const id of selected.value) { const item = imports.value.find(m => `${m.source}:${m.id}` === id); if (item) await extensionRequest('IMPORT_MATCH', { source: item.source, id: item.id }) } selected.value = []; await updateState(); notice.value = t('cloud.queued') }) }
function selectAll() { selected.value = imports.value.map(m => `${m.source}:${m.id}`) }
function toggle(m: SourceMatch) { const id = `${m.source}:${m.id}`; selected.value = selected.value.includes(id) ? selected.value.filter(x => x !== id) : [...selected.value,id] }
let timer: ReturnType<typeof setInterval> | undefined
let polling = false
onMounted(async () => {
  const session = route.query.session
  if (typeof session === 'string') { setCloudSession(session); await router.replace('/cloud') }
  try { await extensionRequest('PING', {}, 2000); installed.value = true } catch { /* installation card remains visible */ }
  if (signedIn.value) await run(async () => { await recent.refresh(); if (installed.value) { await pair(); await updateState() } })
  timer = setInterval(async () => {
    if (polling || !signedIn.value || !installed.value || document.hidden) return
    polling = true
    try { const hadJobs = state.value.active.length > 0; await updateState(); if (hadJobs || state.value.active.length) await recent.refresh() } catch { /* keep the last successful state */ } finally { polling = false }
  },5000)
})
onUnmounted(() => clearInterval(timer))
</script>

<template>
  <div class="cloud-page"><div class="cloud-content">
    <header class="cloud-header"><div><p class="eyebrow">CS2D / MATCHROOM</p><h1>{{ t('cloud.title') }}</h1><p>{{ t('cloud.subtitle') }}</p></div><RouterLink :to="UPLOAD_PATH" class="secondary">{{ t('cloud.openFile') }} ↗</RouterLink></header>
    <section class="storage-banner"><span class="cloud-symbol">☁</span><div><strong>{{ t('cloud.storageTitle') }}</strong><p>{{ t('cloud.storageBody') }}</p></div><div class="storage-number"><strong>{{ fmtSize(recent.totalBytes.value) }}</strong><small>/ {{ fmtSize(recent.maxBytes.value) }}</small></div></section>
    <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="notice" role="status" class="notice">{{ notice }}</p>
    <section v-if="!signedIn" class="login-card"><span class="eyebrow">STEAM OPENID</span><h2>{{ t('cloud.loginTitle') }}</h2><p>{{ t('cloud.loginBody') }}</p><a :href="steamLoginUrl()" class="primary" :aria-disabled="!CLOUD_API">{{ t('cloud.signIn') }} →</a><small>{{ t('cloud.private') }}</small></section>
    <template v-else>
      <div class="source-grid"><section class="source-card"><div class="source-heading"><span class="source-mark faceit">F</span><div><h2>FACEIT</h2><p>{{ state.faceit?.nickname || t('cloud.connectFaceit') }}</p></div><span v-if="state.faceit" class="connected">{{ t('cloud.connected') }}</span></div><p>{{ t('cloud.faceitBody') }}</p><div class="source-controls"><input v-model="nickname" :placeholder="t('cloud.nickname')" aria-label="FACEIT nickname"><button class="primary" :disabled="!installed || loading" @click="syncFaceit">{{ t('cloud.sync') }}</button></div></section>
      <section class="source-card"><div class="source-heading"><span class="source-mark steam">S</span><div><h2>Steam</h2><p>{{ state.steam?.steamId || t('cloud.steamHistory') }}</p></div><span v-if="state.steam" class="connected">{{ t('cloud.connected') }}</span></div><p>{{ t('cloud.steamBody') }}</p><button class="secondary" :disabled="!installed || loading" @click="syncSteam">{{ t('cloud.syncSteam') }} ↗</button></section></div>
      <section v-if="!installed" class="extension-card"><div><h2>{{ t('cloud.extensionTitle') }}</h2><p>{{ t('cloud.extensionBody') }}</p><ol><li>{{ t('cloud.install1') }}</li><li>{{ t('cloud.install2') }}</li><li>{{ t('cloud.install3') }}</li></ol></div><a :href="extensionDownload" download class="primary">{{ t('cloud.downloadExtension') }} ↓</a></section>
      <label class="voice-setting"><input v-model="keepCloudVoice" type="checkbox">{{ t('cloud.keepVoice') }}<small>{{ t('cloud.voiceHint') }}</small></label>
      <section v-if="state.active.length || cloudBusy" class="jobs"><h2>{{ t('cloud.processing') }}</h2><p v-if="cloudBusy">{{ t('cloud.cloudUpload') }} · {{ cloudProgress }}%</p><div v-for="job in state.active" :key="job.matchId"><span>{{ job.matchId }}</span><strong :class="{error:job.error}">{{ job.error || t(`cloud.phase.${job.phase}`) }}</strong></div></section>
      <section v-if="imports.length" class="imports-panel"><div class="panel-heading"><div><h2>{{ t('cloud.available') }} <span>{{ imports.length }}</span></h2><p>{{ t('cloud.expiryHint') }}</p></div><div class="button-row"><button class="secondary" @click="selectAll">{{ t('cloud.selectAll') }}</button><button class="primary" :disabled="loading || !selected.length" @click="importSelected">{{ t('cloud.import') }} ({{ selected.length }})</button></div></div><div class="import-list"><label v-for="m in imports" :key="`${m.source}:${m.id}`"><input type="checkbox" :checked="selected.includes(`${m.source}:${m.id}`)" @change="toggle(m)"><b>{{ m.source.toUpperCase() }}</b><span>{{ m.label }}</span><small>{{ m.kills != null ? `${m.kills} K · ${m.hsPercent ?? 0}% HS` : '' }}</small></label></div></section>
    </template>
    <section class="library-section"><div class="panel-heading"><div><h2>{{ t('cloud.yourMatches') }} <span>{{ recent.list.value.length }}</span></h2><p>{{ t('cloud.recordsHint') }}</p></div><button v-if="signedIn" class="secondary" :disabled="loading" @click="run(recent.refresh)">↻ {{ t('cloud.refresh') }}</button></div><div class="library-filters"><input v-model="search" :placeholder="t('cloud.search')"><select v-model="sort"><option value="date">{{ t('cloud.sortDate') }}</option><option value="deagle">{{ t('cloud.sortDeagle') }}</option><option value="deagleHs">{{ t('cloud.sortDeagleHs') }}</option><option value="hs">{{ t('cloud.sortHs') }}</option></select></div>
      <div v-if="records.length" class="match-grid"><RouterLink v-for="m in records" :key="m.id" :to="`${demoPath(m.id)}/overview`" class="cloud-match"><div class="match-art" :style="{backgroundImage:`linear-gradient(0deg,#10151e,transparent),url('${mapImage(m.map)}')`}"><span>{{ m.storage === 'cloud' ? t('cloud.cloudBadge') : t('cloud.sessionBadge') }}</span><strong>{{ prettyMap(m.map) }}</strong><b>{{ m.scoreCt }} : {{ m.scoreT }}</b></div><div class="match-details"><h3>{{ m.title || m.fileName }}</h3><p v-if="m.me">{{ m.me.kills }} / {{ m.me.deaths }} / {{ m.me.assists }} <span>{{ m.me.hsPercent.toFixed(1) }}% HS</span></p><p v-if="m.deagle" class="deagle-record">Desert Eagle <strong>{{ m.deagle.kills }} K · {{ m.deagle.headshots }} HS</strong></p><small>{{ fmtSize(m.fileSize) }} · {{ m.analysis?.moments.length ?? 0 }} {{ t('cloud.moments') }}</small></div></RouterLink></div><div v-else class="library-empty"><span>↗</span><h3>{{ t('cloud.emptyTitle') }}</h3><p>{{ t('cloud.emptyBody') }}</p></div>
    </section><footer>{{ t('cloud.footer') }} <button v-if="signedIn" type="button" @click="setCloudSession('');recent.list.value=[]">{{ t('cloud.signOut') }}</button></footer>
  </div></div>
</template>

<style scoped>
